using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends email messages.</summary>
public sealed class EmailClient
{
    public bool SendEmail(Message message)
    {
#pragma warning disable CS0612, CS0618 // No replacement API is present in the supplied context.
        return MailApiV1.Send(message.Recipient.EmailAddress, message.Subject, message.Body);
#pragma warning restore CS0612, CS0618
    }
}
